#include <zephyr/drivers/uart.h>
#include <zephyr/kernel.h>
#include <zephyr/net/net_if.h>
#include <zephyr/net/net_pkt.h>
#include <zephyr/net/pcap.h>
#include <zephyr/ztest.h>
#include <zephyr/drivers/modem/modem_ppp.h>

/* PPP link-layer header (RFC 1661 section 2) */
struct ppp_hdr {
	uint8_t address;
	uint8_t control;
} __packed;

/* PPP protocol field (RFC 1661 section 2) */
struct ppp_proto {
	uint16_t proto;
} __packed;

/* PPP LCP code */
#define PPP_LCP_CONFIGURE_REQ 0x01

/* PPP LCP configure request (RFC 1661 section 6.2) */
struct ppp_lcp_config_req {
	uint8_t code;
	uint8_t id;
	uint16_t len;
	uint8_t data[0];
} __packed;

/* Test data */
static const uint8_t ppp_lcp_config_req_frame[] = {0xff, 0x03, 0xc0, 0x21, 0x01,
						   0x01, 0x00, 0x04};
static const uint8_t ip_frame[] = {0x45, 0x00, 0x00, 0x20, 0x00, 0x01, 0x00, 0x00, 0x40, 0x11,
				   0x77, 0x59, 0xc0, 0xa8, 0x00, 0x02, 0xc0, 0xa8, 0x00, 0x01};
static uint8_t large_ip_frame[2048];
static uint8_t ppp_ip_frame[sizeof(ip_frame) + 4];
static uint8_t large_ppp_ip_frame[sizeof(large_ip_frame) + 4];

/* Test configuration */
#define TEST_UART_NODE DT_NODELABEL(test_uart)
#define PPP_MTU 1500

/* pcap configuration */
#define PCAP_FILE "modem_ppp.pcap"

/* List of received packets */
static K_FIFO_DEFINE(received_packets);

/* Network interface */
static struct net_if *ppp_iface;

/* Modem pipe */
static struct modem_pipe *ppp_pipe;

static void generate_large_ip_frame(void)
{
	size_t ip_frame_len = sizeof(ip_frame);

	memcpy(large_ip_frame, ip_frame, ip_frame_len);
	for (size_t i = ip_frame_len; i < sizeof(large_ip_frame); i++) {
		large_ip_frame[i] = (uint8_t)i;
	}
}

static void create_ppp_ip_frame(uint8_t *ppp_frame, const uint8_t *ip_frame_data,
				size_t ip_frame_size)
{
	struct ppp_hdr *hdr = (struct ppp_hdr *)ppp_frame;
	struct ppp_proto *proto = (struct ppp_proto *)(ppp_frame + sizeof(*hdr));

	hdr->address = 0xff;
	hdr->control = 0x03;
	proto->proto = htons(PPP_IP);
	memcpy(ppp_frame + sizeof(*hdr) + sizeof(*proto), ip_frame_data, ip_frame_size);
}

static int test_iface_send(const struct device *dev, struct net_pkt *pkt)
{
	zassert_equal(dev, net_if_get_device(ppp_iface));

	net_pkt_unref(pkt);

	return 0;
}

static void test_iface_init(struct net_if *iface)
{
	const struct device *dev = net_if_get_device(iface);

	zassert_not_null(dev);
	net_if_set_mtu(iface, PPP_MTU);
	ppp_iface = iface;
}

NET_DEVICE_INIT(test_ppp, "test_ppp", test_iface_init, NULL, NULL, NULL,
		CONFIG_KERNEL_INIT_PRIORITY_DEFAULT, NULL, PPP_MTU);

static struct net_if_api test_if_api = {
	.iface_api.init = test_iface_init,
	.send = test_iface_send,
};

static int ppp_open(void *data)
{
	return 0;
}

static int ppp_transmit(void *data, const uint8_t *buf, size_t size)
{
	return 0;
}

static int ppp_receive(void *data, uint8_t *buf, size_t size)
{
	return 0;
}

static int ppp_close(void *data)
{
	return 0;
}

static const struct modem_pipe_api ppp_pipe_api = {
	.open = ppp_open,
	.transmit = ppp_transmit,
	.receive = ppp_receive,
	.close = ppp_close,
};

MODEM_PIPE_DEFINE(ppp_pipe_dev, ppp_pipe, 1024, 1024);

static int ppp_proto_ip_cb(struct modem_ppp *ppp, struct net_pkt *pkt)
{
	k_fifo_put(&received_packets, pkt);
	return 0;
}

static const struct modem_ppp_proto ppp_protos[] = {
	{
		.protocol = PPP_IP,
		.handler = ppp_proto_ip_cb,
	},
};

static struct modem_ppp_config ppp_config = {
	.iface = &NET_DEVICE_NAME_GET(test_ppp),
	.pcap_file = PCAP_FILE,
	.protos = ppp_protos,
	.protos_len = ARRAY_SIZE(ppp_protos),
};

MODEM_PPP_DEFINE(ppp, ppp_config);

static void clear_received_packets(void)
{
	struct net_pkt *pkt;

	while ((pkt = k_fifo_get(&received_packets, K_NO_WAIT))) {
		net_pkt_unref(pkt);
	}
}

static void put_and_validate_wrapped_frame(const uint8_t *frame, size_t frame_len,
					   int expected_packets)
{
	size_t received_packets_len;
	struct net_pkt *pkt;

	clear_received_packets();

	/* Start of frame */
	modem_ppp_process_byte(&ppp, 0x7e);

	for (int i = 0; i < frame_len; i++) {
		if (frame[i] == 0x7e || frame[i] == 0x7d) {
			modem_ppp_process_byte(&ppp, 0x7d);
			modem_ppp_process_byte(&ppp, frame[i] ^ 0x20);
		} else {
			modem_ppp_process_byte(&ppp, frame[i]);
		}
	}

	/* End of frame */
	modem_ppp_process_byte(&ppp, 0x7e);

	k_sleep(K_MSEC(100));

	received_packets_len = 0;
	while ((pkt = k_fifo_get(&received_packets, K_NO_WAIT))) {
		received_packets_len++;
		net_pkt_unref(pkt);
	}

	zassert_equal(received_packets_len, expected_packets,
		      "invalid number of packets received");
}

static void *test_modem_ppp_suite_setup(void)
{
	generate_large_ip_frame();
	create_ppp_ip_frame(ppp_ip_frame, ip_frame, sizeof(ip_frame));
	create_ppp_ip_frame(large_ppp_ip_frame, large_ip_frame, sizeof(large_ip_frame));
	return NULL;
}

static void test_modem_ppp_before(void *data)
{
	clear_received_packets();
}

static void test_modem_ppp_after(void *data)
{
	modem_ppp_stop(&ppp);
}

ZTEST_SUITE(modem_ppp, NULL, test_modem_ppp_suite_setup, test_modem_ppp_before,
	    test_modem_ppp_after, NULL);

ZTEST(modem_ppp, test_ip_frame_receive)
{
	put_and_validate_wrapped_frame(ppp_ip_frame, sizeof(ppp_ip_frame), 1);
}

ZTEST(modem_ppp, test_ip_frame_receive_large)
{
	put_and_validate_wrapped_frame(large_ppp_ip_frame, sizeof(large_ppp_ip_frame), 1);
}

ZTEST(modem_ppp, test_ip_frame_send)
{
	struct net_pkt *pkt;
	int ret;

	ret = modem_ppp_start(&ppp);
	zassert_ok(ret);

	pkt = net_pkt_alloc_with_buffer(ppp_iface, sizeof(ip_frame), AF_INET, IPPROTO_ICMP,
					K_NO_WAIT);
	zassert_not_null(pkt);

	net_buf_add_mem(pkt->buffer, ip_frame, sizeof(ip_frame));

	ret = net_if_send_data(ppp_iface, pkt);
	zassert_ok(ret);
}

ZTEST(modem_ppp, test_ip_frame_send_large)
{
	struct net_pkt *pkt;
	int ret;

	ret = modem_ppp_start(&ppp);
	zassert_ok(ret);

	pkt = net_pkt_alloc_with_buffer(ppp_iface, sizeof(large_ip_frame), AF_INET, IPPROTO_ICMP,
					K_NO_WAIT);
	zassert_not_null(pkt);

	net_buf_add_mem(pkt->buffer, large_ip_frame, sizeof(large_ip_frame));

	ret = net_if_send_data(ppp_iface, pkt);
	zassert_ok(ret);
}

ZTEST(modem_ppp, test_ip_frame_send_multiple)
{
	struct net_pkt *pkt;
	int ret;

	ret = modem_ppp_start(&ppp);
	zassert_ok(ret);

	for (int i = 0; i < 10; i++) {
		pkt = net_pkt_alloc_with_buffer(ppp_iface, sizeof(ip_frame), AF_INET,
						IPPROTO_ICMP, K_NO_WAIT);
		zassert_not_null(pkt);

		net_buf_add_mem(pkt->buffer, ip_frame, sizeof(ip_frame));

		ret = net_if_send_data(ppp_iface, pkt);
		zassert_ok(ret);
	}
}

ZTEST(modem_ppp, test_ppp_frame_receive)
{
	put_and_validate_wrapped_frame(ppp_lcp_config_req_frame,
				       sizeof(ppp_lcp_config_req_frame), 0);
}
